# Unoptimized (/Od /Ob1, no EH) EASTL vector::swap(V&) of a 5-dword vector object (b,e,c + allocator):
#   if (alloc_eq() && fast-ok) { swap 3 ptrs } else if (alloc_ne()) {dead copy} else { tmp(*this); assign both ways; ~tmp }
# ~tmp inlines a trivial destruct loop (which carries a block of inline-chain locals) then calls the free helper.
# Frame size/loop slot vary per instance (padA dwords = (frame-96)/4); stride is the element size.
PATTERN = 'push ebp ; mov ebp, esp ; sub esp, N ; mov dword ptr [ebp - N], ecx ; mov eax, N ; test eax, eax ; je +N ; mov ecx, dword ptr [ebp - N] ; cmp dword ptr [ecx], N ; je +N ; mov edx, dword ptr [ebp - N] ; mov eax, dword ptr [edx] ; cmp dword ptr [eax - N], N ; je +N ; mov ecx, dword ptr [ebp + N] ; cmp dword ptr [ecx], N ; je +N ; mov edx, dword ptr [ebp + N] ; mov eax, dword ptr [edx] ; cmp dword ptr [eax - N], N ; je +N ; mov ecx, dword ptr [ebp - N] ; mov edx, dword ptr [ecx] ; mov dword ptr [ebp - N], edx ; mov eax, dword ptr [ebp - N] ; mov ecx, dword ptr [ebp + N] ; mov edx, dword ptr [ecx] ; mov dword ptr [eax], edx ; mov eax, dword ptr [ebp + N] ; mov ecx, dword ptr [ebp - N] ; mov dword ptr [eax], ecx ; mov edx, dword ptr [ebp + N] ; add edx, N ; mov dword ptr [ebp - N], edx ; mov eax, dword ptr [ebp - N] ; add eax, N ; mov dword ptr [ebp - N], eax ; mov ecx, dword ptr [ebp - N] ; mov edx, dword ptr [ecx] ; mov dword ptr [ebp - N], edx ; mov eax, dword ptr [ebp - N] ; mov ecx, dword ptr [ebp - N] ; mov edx, dword ptr [ecx] ; mov dword ptr [eax], edx ; mov eax, dword ptr [ebp - N] ; mov ecx, dword ptr [ebp - N] ; mov dword ptr [eax], ecx ; mov edx, dword ptr [ebp + N] ; add edx, N ; mov dword ptr [ebp - N], edx ; mov eax, dword ptr [ebp - N] ; add eax, N ; mov dword ptr [ebp - N], eax ; mov ecx, dword ptr [ebp - N] ; mov edx, dword ptr [ecx] ; mov dword ptr [ebp - N], edx ; mov eax, dword ptr [ebp - N] ; mov ecx, dword ptr [ebp - N] ; mov edx, dword ptr [ecx] ; mov dword ptr [eax], edx ; mov eax, dword ptr [ebp - N] ; mov ecx, dword ptr [ebp - N] ; mov dword ptr [eax], ecx ; jmp +N ; xor edx, edx ; je +N ; mov eax, dword ptr [ebp - N] ; mov ecx, dword ptr [eax] ; mov dword ptr [ebp - N], ecx ; mov edx, dword ptr [ebp - N] ; mov eax, dword ptr [ebp + N] ; mov ecx, dword ptr [eax] ; mov dword ptr [edx], ecx ; mov edx, dword ptr [ebp + N] ; mov eax, dword ptr [ebp - N] ; mov dword ptr [edx], eax ; mov ecx, dword ptr [ebp + N] ; add ecx, N ; mov dword ptr [ebp - N], ecx ; mov edx, dword ptr [ebp - N] ; add edx, N ; mov dword ptr [ebp - N], edx ; mov eax, dword ptr [ebp - N] ; mov ecx, dword ptr [eax] ; mov dword ptr [ebp - N], ecx ; mov edx, dword ptr [ebp - N] ; mov eax, dword ptr [ebp - N] ; mov ecx, dword ptr [eax] ; mov dword ptr [edx], ecx ; mov edx, dword ptr [ebp - N] ; mov eax, dword ptr [ebp - N] ; mov dword ptr [edx], eax ; mov ecx, dword ptr [ebp + N] ; add ecx, N ; mov dword ptr [ebp - N], ecx ; mov edx, dword ptr [ebp - N] ; add edx, N ; mov dword ptr [ebp - N], edx ; mov eax, dword ptr [ebp - N] ; mov ecx, dword ptr [eax] ; mov dword ptr [ebp - N], ecx ; mov edx, dword ptr [ebp - N] ; mov eax, dword ptr [ebp - N] ; mov ecx, dword ptr [eax] ; mov dword ptr [edx], ecx ; mov edx, dword ptr [ebp - N] ; mov eax, dword ptr [ebp - N] ; mov dword ptr [edx], eax ; jmp +N ; mov ecx, dword ptr [ebp - N] ; push ecx ; lea ecx, [ebp - N] ; call EXT ; mov edx, dword ptr [ebp + N] ; push edx ; mov ecx, dword ptr [ebp - N] ; call EXT ; lea eax, [ebp - N] ; push eax ; mov ecx, dword ptr [ebp + N] ; call EXT ; mov ecx, dword ptr [ebp - N] ; mov dword ptr [ebp - N], ecx ; jmp +N ; mov edx, dword ptr [ebp - N] ; add edx, N ; mov dword ptr [ebp - N], edx ; mov eax, dword ptr [ebp - N] ; cmp eax, dword ptr [ebp - N] ; jae +N ; jmp +N ; lea ecx, [ebp - N] ; call EXT ; mov esp, ebp ; pop ebp ; ret N'
FLAGS = ["/Od", "/Ob1", "/MD", "/Gy", "/TP", "/GR-"]
PRELUDE = "template<class T> inline void sw(T& a, T& b) { T t = a; a = b; b = t; }\n"
def emit(va, A, N):
    t = "%08x" % va
    frame, stride = N[0], N[-6]
    pad = (frame - 96) // 4
    src = ("struct E_@ { char pad[%d]; };\n"
           "inline void destruct_@(E_@* first, E_@* last) { int padA[%d]; for (E_@* p = first; p < last; ++p) {} { int q[3]; } }\n"
           "struct V_@ { E_@* b; E_@* e; E_@* c; int x; int y;\n"
           " V_@(const V_@&); void assign(const V_@&); void freeb();\n"
           " ~V_@() { destruct_@(b, e); freeb(); }\n"
           " static int t1() { return 1; } static int t2() { return 0; }\n"
           " void FUN_@(V_@& o); };\n"
           "void V_@::FUN_@(V_@& o) {\n"
           " if (t1() && ((!b || ((int*)b)[-1]) && (!o.b || ((int*)o.b)[-1]))) { sw(b, o.b); sw(e, o.e); sw(c, o.c); }\n"
           " else if (t2()) { sw(b, o.b); sw(e, o.e); sw(c, o.c); }\n"
           " else { V_@ tmp(*this); assign(o); o.assign(tmp); } }") % (stride, pad)
    return src.replace("@", t), "?FUN_%s@V_%s@@QAEXAAU1@@Z" % (t, t)
